 "A file name was not saved. Try again.": "Nazwa pliku nie została zapisana. Spróbuj ponownie.",
 "A file named \"{name}\" is already here. Rename it or remove the one already added.": "Plik o nazwie „{name}” już tu jest. Zmień nazwę lub usuń ten już dodany.",
 "A file stayed in Storelib": "Plik został w Storelib",
 "A file was too big for GitHub": "Plik był za duży dla GitHub",
 "A fine grain over the whole wallpaper": "Drobne ziarno na całym tle",
 "A first order happens once, so each person goes through this once: when they first buy from you.": "Pierwsze zamówienie zdarza się raz, więc każdy przejdzie to raz: przy pierwszym zakupie u Ciebie.",
 "A first visit opens in the language the visitor's browser asks for, once, on your website and your storelib.com page. A close match gets a small offer instead.": "Pierwsza wizyta otwiera się raz w języku, o który prosi przeglądarka odwiedzającego, na Twojej stronie i stronie storelib.com. Przy podobnym języku pojawia się mała propozycja.",
 "A fixed UTC offset does not move with daylight saving.": "Stałe przesunięcie UTC nie zmienia się wraz z czasem letnim.",
 "A fixed amount is at most $100,000.": "Stała kwota może wynosić najwyżej 100 000 USD.",
 "A fixed amount is at most 100,000.": "Stała kwota to maksymalnie 100 000.",
 "A flow can have up to {maxSteps} steps.": "Przepływ może mieć maksymalnie {maxSteps} kroków.",
 "A food and drinks menu": "Menu z jedzeniem i napojami",
 "A form people fill in on your page": "Formularz do wypełnienia na twojej stronie",
 "A free file for an email": "Darmowy plik za adres e-mail",
 "A free order has no payout.": "Bezpłatne zamówienie nie ma wypłaty.",
 "A fulfillment center": "Centrum logistyczne",
 "A fulfillment provider (not connected)": "Operator logistyczny (niepołączony)",
 "A gallery holds pictures and videos.": "Galeria zawiera obrazy i wideo.",
 "A gallery holds up to 24 pictures.": "Galeria mieści do 24 zdjęć.",
 "A gallery holds {max}.": "Galeria mieści {max}.",
 "A gallery holds {max}. The first {length} were added.": "Galeria mieści {max}. Dodano pierwsze {length}.",
 "A heading, a line and a button": "Nagłówek, linijka tekstu i przycisk",
 "A holder can give up their seat and get their money back {value}.": "Posiadacz może zrezygnować z miejsca i odzyskać pieniądze {value}.",
 "A label, never converted": "Etykieta, nigdy nie jest przeliczana",
 "A language is on your website once it is published. Translating it to the end publishes it for you. Anything not translated yet shows in your default language.": "Język pojawia się na Twojej stronie po opublikowaniu. Przetłumaczenie go do końca publikuje go za Ciebie. To, co nie jest jeszcze przetłumaczone, wyświetla się w Twoim języku domyślnym.",
 "A level": "Poziom",
 "A light that circles your profile image": "Światło wokół obrazu profilowego",
 "A limit per order is 1 to {max}.": "Limit na zamówienie to od 1 do {max}.",
 "A line about the community": "Jedno zdanie o społeczności",
 "A line each, on the community's page.": "Po jednej linijce na stronie społeczności.",
 "A line each, with a check beside it.": "Po jednej linii, z ptaszkiem obok.",
 "A line from you (optional)": "Kilka słów od Ciebie (opcjonalnie)",
 "A line of your own above the footer, such as a returns note. The address and links stay.": "Twoja własna linia nad stopką, np. informacja o zwrotach. Adres i linki zostają.",
 "A line of your own at the foot of the email. The links and the note on why it came stay.": "Twoja własna linia na dole e-maila. Linki i informacja, dlaczego przyszedł, zostają.",
 "A line or two about them.": "Zdanie lub dwa o tej osobie.",
 "A line or two under the title on the blog page. Left empty, the post's first words are used.": "Linijka lub dwie pod tytułem na stronie bloga. Gdy puste, użyjemy pierwszych słów wpisu.",
 "A line over the header with how much more gets free shipping.": "Linijka nad nagłówkiem z informacją, ile brakuje do darmowej wysyłki.",
 "A line under it (optional)": "Linia pod spodem (opcjonalnie)",
 "A line under it for the buyer (optional)": "Linia pod spodem dla kupującego (opcjonalnie)",
 "A line under question {value}": "Linia pod pytaniem {value}",
 "A line under the title": "Linijka pod tytułem",
 "A link drawn as a button": "Link wyglądający jak przycisk",
 "A link is not an address yet. Fix it or remove it.": "Jeden link nie jest jeszcze adresem. Popraw go lub usuń.",
 "A link needs a full web address, like https://example.com/guide.": "Link musi być pełnym adresem, np. https://example.com/guide.",
 "A link they get right away: a free guide, a video, a group chat.": "Link, który dostają od razu: darmowy poradnik, film, czat grupowy.",
 "A live call every week": "Rozmowa na żywo co tydzień",
 "A livestream link starts with https://": "Link do transmisji zaczyna się od https://",
 "A location": "Lokalizacja",
 "A location is any place that holds your stock: your home, a warehouse, a fulfillment center, or a supplier who ships for you.": "Lokalizacja to każde miejsce z Twoim towarem: dom, magazyn, centrum logistyczne lub dostawca, który wysyła za Ciebie.",
 "A market is a group of countries. Give it a currency and its visitors see your prices converted at the day's European Central Bank rate, with the rounding you pick.": "Rynek to grupa krajów. Nadaj mu walutę, a odwiedzający zobaczą ceny przeliczone po dziennym kursie Europejskiego Banku Centralnego, z wybranym zaokrągleniem.",
 "A measurement, converted between cm and in": "Pomiar, przeliczany między cm a in",
 "A meeting link starts with https://": "Link do spotkania zaczyna się od https://",
 "A member muted or banned here can still read the community and its chat. Reports of messages are in Moderation.": "Członek wyciszony lub wykluczony tutaj nadal może czytać społeczność i jej czat. Zgłoszenia wiadomości są w Moderacji.",
 "A mix is fine. Each location says who ships from it, and each product says which location it ships from.": "Mieszanka jest w porządku. Każda lokalizacja mówi, kto z niej wysyła, a każdy produkt, skąd wychodzi.",
 "A mix of these": "Mieszanka tych opcji",
 "A month": "Miesięcznie",
 "A name cannot start with _": "Nazwa nie może zaczynać się od _",
 "A name is up to {max} characters.": "Nazwa może mieć maksymalnie {max} znaków.",
 "A name, a message or a photo, asked at checkout.": "Imię, wiadomość lub zdjęcie, o które pytamy przy zakupie.",
 "A negative number takes points away.": "Liczba ujemna odejmuje punkty.",
 "A new branch name makes that branch.": "Nowa nazwa gałęzi tworzy tę gałąź.",
 "A new invite went to {email}.": "Nowe zaproszenie wysłano do {email}.",
 "A new language starts unpublished: translate it, check it, then publish. Anything not translated yet shows in {name}.": "Nowy język startuje jako nieopublikowany: przetłumacz, sprawdź i opublikuj. Nieprzetłumaczone treści są wyświetlane w języku: {name}.",
 "A new link went to {email}. The old one stops working.": "Nowy link wysłano na {email}. Stary przestaje działać.",
 "A new one: Storelib subscribers": "Nowy: Storelib subscribers",
 "A new video lesson every week": "Nowa lekcja wideo co tydzień",
 "A note, a tip or a warning": "Notatka, wskazówka lub ostrzeżenie",
 "A notification on this computer when you make a sale or a payout is ready.": "Powiadomienie na tym komputerze, gdy coś sprzedasz lub wypłata będzie gotowa.",
 "A notification on this phone when you make a sale or a payout is ready.": "Powiadomienie na tym telefonie, gdy coś sprzedasz lub wypłata będzie gotowa.",
 "A notification on this phone when you make a sale or a payout is ready. Turn it off in your phone's settings.": "Powiadomienie na tym telefonie, gdy coś sprzedasz lub wypłata będzie gotowa. Wyłącz je w ustawieniach telefonu.",
 "A nudge when your first product or payment setup is not done yet.": "Przypomnienie, gdy pierwszy produkt lub konfiguracja płatności nie są jeszcze gotowe.",
 "A one time price, paid inside the community.": "Jednorazowa cena, płatna w społeczności.",
 "A pack of sessions, booked by link": "Pakiet sesji rezerwowany przez link",
