 "A page": "Strona",
 "A paragraph": "Akapit",
 "A partner who packs and ships for you": "Partner, który pakuje i wysyła za Ciebie",
 "A partner: email each order to them": "Partner: wysyłaj mu każde zamówienie e-mailem",
 "A payment the card's owner didn't make.": "Płatność, której nie wykonał właściciel karty.",
 "A payout didn't go through. Add the account you want paid into.": "Wypłata nie doszła. Dodaj konto, na które chcesz otrzymywać pieniądze.",
 "A payout is on its way to your bank": "Wypłata jest w drodze do Twojego banku",
 "A percent off is 0 to {maxPercent}.": "Rabat procentowy to od 0 do {maxPercent}.",
 "A percent off is 1 to {maxPercent}.": "Rabat procentowy wynosi od 1 do {maxPercent}.",
 "A percentage is at most 100.": "Procent może wynosić najwyżej 100.",
 "A personal note from you, right after someone buys.": "Osobista wiadomość od Ciebie zaraz po zakupie.",
 "A photo or a slideshow": "Zdjęcie lub pokaz slajdów",
 "A photo the buyer uploads: JPG, PNG or WEBP, up to 10 MB.": "Zdjęcie przesłane przez kupującego: JPG, PNG lub WEBP, do 10 MB.",
 "A picture": "Zdjęcie",
 "A picture did not upload. Try again.": "Jeden obraz nie został przesłany. Spróbuj ponownie.",
 "A picture, moved": "Zdjęcie, przesunięte",
 "A picture, or an intro video, at the top. It also shows on your card in Explore.": "Zdjęcie lub film powitalny na górze. Widać je też na Twojej karcie w Odkrywaj.",
 "A place for your members: posts, chat, Learn and live events. Free, paid every month or year, or by invite only.": "Miejsce dla członków: posty, czat, Nauka i wydarzenia na żywo. Za darmo, płatne miesięcznie lub rocznie albo tylko na zaproszenie.",
 "A place of your own": "Własne miejsce",
 "A portfolio for my wedding and portrait photography with galleries, packages and prices, and a contact form.": "Portfolio mojej fotografii ślubnej i portretowej z galeriami, pakietami i cenami oraz formularzem kontaktowym.",
 "A post on {name}'s blog.": "Wpis na blogu {name}.",
 "A post, form, player or calendar": "Post, formularz, odtwarzacz lub kalendarz",
 "A price is between $1 and {top}.": "Cena musi wynosić od 1 $ do {top}.",
 "A print partner makes this when it sells, so there is no stock to count.": "Partner drukujący wykonuje to po sprzedaży, więc nie ma stanów do liczenia.",
 "A product": "Produkt",
 "A product in it was deleted. Edit it to fix.": "Usunięto produkt z oferty. Edytuj ją, aby to poprawić.",
 "A product in this offer is no longer in your store, so the offer can't apply.": "Produktu z tej oferty nie ma już w twoim sklepie, więc oferta nie może zadziałać.",
 "A product taxed differently here, like books or food at a reduced rate.": "Produkt opodatkowany tu inaczej, np. książki lub żywność ze stawką obniżoną.",
 "A product that is no longer published": "Produkt, który nie jest już opublikowany",
 "A product that was deleted": "Usunięty produkt",
 "A product you archive is kept here, off your page, until you restore it.": "Zarchiwizowany produkt zostaje tutaj, poza Twoją stroną, dopóki go nie przywrócisz.",
 "A product you sell": "Produkt, który sprzedajesz",
 "A product, payouts, then your link.": "Produkt, wypłaty, a potem Twój link.",
 "A program is modules of lessons: videos, notes and files. Members find it under Learn.": "Program to moduły z lekcjami: wideo, notatki i pliki. Członkowie znajdą go w Nauce.",
 "A program of lessons, or a course you already sell.": "Program lekcji lub kurs, który już sprzedajesz.",
 "A public https address": "Publiczny adres https",
 "A public https address of the design, a PDF or PNG at print size.": "Publiczny adres https projektu, PDF lub PNG w rozmiarze do druku.",
 "A push from GitHub": "Wypchnięcie z GitHub",
 "A push to {branch} wasn't brought in": "Wypchnięcie do {branch} nie zostało pobrane",
 "A push to {pushed} wasn't brought in. This site follows {branch}.": "Push do {pushed} nie został pobrany. Ta strona śledzi {branch}.",
 "A question": "Pytanie",
 "A quick introduction on the community's card, up to 160 characters.": "Krótkie przedstawienie na karcie społeczności, do 160 znaków.",
 "A reason you delete stays on the returns and refunds that already used it.": "Usunięty powód zostaje przy zwrotach i refundacjach, które już go użyły.",
 "A refund window is a whole number of hours, up to {value}.": "Okres zwrotu to pełna liczba godzin, maksymalnie {value}.",
 "A revoked invite stops working at once.": "Cofnięte zaproszenie od razu przestaje działać.",
 "A row of your latest posts": "Rząd Twoich najnowszych postów",
 "A row of your products, always up to date": "Rząd Twoich produktów, zawsze aktualny",
 "A sale": "Sprzedaż",
 "A sales channel is a place your products are listed. Storelib runs three: your online store, your creator page and Explore.": "Kanał sprzedaży to miejsce, w którym wystawiasz produkty. Storelib prowadzi trzy: sklep online, stronę twórcy i Odkrywaj.",
 "A sample membership, drawn the way the real email is sent. The real email has the member's own plan, price and dates.": "Przykładowe członkostwo, narysowane tak, jak wysyłany jest prawdziwy e-mail. Prawdziwy e-mail zawiera plan, cenę i daty członka.",
 "A sample order with your store's name. The real email has the buyer's own items, address and order.": "Przykładowe zamówienie z nazwą sklepu. Prawdziwy e-mail zawiera produkty, adres i zamówienie kupującego.",
 "A sample order, drawn the way the real email is sent. The real email has the buyer's own items, address and order.": "Przykładowe zamówienie, narysowane tak, jak wysyłany jest prawdziwy e-mail. Prawdziwy e-mail ma własne produkty, adres i zamówienie kupującego.",
 "A sample with your store's name, logo and colour.": "Przykład z nazwą, logo i kolorem Twojego sklepu.",
 "A save is still going. Leaving now could lose it.": "Zapisywanie wciąż trwa. Wyjście teraz może je przerwać.",
 "A section you add starts on this scheme.": "Nowa sekcja zaczyna od tego schematu.",
 "A section, in the table of contents": "Sekcja, w spisie treści",
 "A segment": "Segment",
 "A service code, like usps_priority. Empty: the cheapest.": "Kod usługi, na przykład usps_priority. Puste: najtańsza.",
 "A shared folder, a template, a recording. Only members who open the item are sent to it.": "Udostępniony folder, szablon, nagranie. Przekierowani zostają tylko członkowie, którzy otwierają element.",
 "A shipping profile is a group of products that ship the same way. Every product starts in the General profile.": "Profil wysyłki to grupa produktów wysyłanych tak samo. Każdy produkt zaczyna w profilu Ogólny.",
 "A shipping rate for where you sell, or local pickup.": "Stawka wysyłki tam, gdzie sprzedajesz, lub odbiór lokalny.",
 "A short bio about yourself...": "Krótkie bio o sobie...",
 "A short list new members see above the feed for their first 30 days, until they finish it or hide it.": "Krótka lista, którą nowi członkowie widzą nad aktualnościami przez pierwsze 30 dni, dopóki jej nie ukończą lub nie ukryją.",
 "A smaller heading": "Mniejszy nagłówek",
 "A space name is up to {max} characters.": "Nazwa przestrzeni może mieć maksymalnie {max} znaków.",
 "A start for a store in {country}. Type your prices, check the days, then press Use this setup. You can change all of it later.": "Początek dla sklepu w kraju {country}. Wpisz ceny, sprawdź dni i naciśnij Użyj tej konfiguracji. Wszystko możesz później zmienić.",
 "A step of your own": "Własny krok",
 "A store can have up to {maxMarkets} markets.": "Sklep może mieć maksymalnie {maxMarkets} rynków.",
 "A store holds {menus} menus.": "Sklep mieści {menus} menu.",
 "A subdomain like mail.yourshop.com keeps this apart from your inbox.": "Subdomena, np. mail.yourshop.com, oddziela to od Twojej skrzynki.",
 "A supplier or manufacturer": "Dostawca lub producent",
 "A supplier ships straight to your buyers.": "Dostawca wysyła bezpośrednio do kupujących.",
