 "A title between your links": "Tytuł między linkami",
 "A title is up to {max} characters.": "Tytuł może mieć maksymalnie {max} znaków.",
 "A translation goes live as soon as it is done. Anything not translated yet shows in your default language.": "Tłumaczenie trafia na stronę, gdy tylko jest gotowe. To, co nie jest jeszcze przetłumaczone, wyświetla się w Twoim języku domyślnym.",
 "A video": "Film",
 "A video here is at most {maxVideo}": "Wideo może mieć tu maksymalnie {maxVideo}",
 "A video, playing on a loop": "Wideo w pętli",
 "A visit is counted when the visitor leaves the page.": "Wizyta jest liczona, gdy odwiedzający opuszcza stronę.",
 "A visitor confirms their review from an email before it posts, and it is not marked Verified buyer or counted in your Storelib rating. A buyer who uses the form is sent their own link instead.": "Odwiedzający potwierdza opinię e-mailem przed publikacją; nie jest oznaczona jako Zweryfikowany kupujący ani liczona do oceny Storelib. Kupujący korzystający z formularza dostaje własny link.",
 "A visitor's details are sent only when their cookie choice allows it. Emails and phone numbers go hashed. Test sales are never sent.": "Dane odwiedzającego są wysyłane tylko wtedy, gdy pozwala na to jego wybór plików cookie. E-maile i numery telefonów są haszowane. Sprzedaże testowe nigdy nie są wysyłane.",
 "A wait at the end does nothing. Add an email after it, or remove it.": "Oczekiwanie na końcu nic nie robi. Dodaj po nim e-mail lub je usuń.",
 "A wait can be up to {maxWaitDays} days.": "Oczekiwanie może trwać do {maxWaitDays} dni.",
 "A wait needs a length of at least 1.": "Oczekiwanie musi trwać co najmniej 1.",
 "A website already uses this name": "Ta nazwa jest już używana przez inną stronę",
 "A website can have up to {maxLanguages} more languages.": "Strona może mieć maksymalnie {maxLanguages} dodatkowych języków.",
