 "An error occurred": "Wystąpił błąd",
 "An error occurred while saving. Please try again.": "Wystąpił błąd podczas zapisywania. Spróbuj ponownie.",
 "An error occurred. Please try again.": "Wystąpił błąd. Spróbuj ponownie.",
 "An export from Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews or Rivyo, or any CSV or JSON file.": "Eksport z Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews lub Rivyo albo dowolny plik CSV lub JSON.",
 "An hour after a buyer leaves checkout without paying, if they asked for news.": "Godzinę po tym, jak kupujący opuści kasę bez płacenia, jeśli prosił o nowości.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Godzinę po porzuceniu kasy bez płatności, jeśli kupujący chciał wiadomości. Włącz w Kasie.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Godzinę po tym, jak ktoś naciśnie Zapłać, a zamówienie nie powstanie. Dostają ją tylko osoby, które zaznaczyły przy płatności „Wysyłaj mi nowości i oferty” lub są na Twojej liście, i zatrzymuje się, gdy tylko kupią.",
