 "An intro video": "Film powitalny",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Zaproszenie jest już zgodą, więc dotyczy to tylko próśb bez zaproszenia.",
 "An invite lasts 1 to 365 days.": "Zaproszenie jest ważne od 1 do 365 dni.",
 "An invite link is the only way in.": "Wejść można tylko przez link z zaproszeniem.",
 "An mp4 or webm address": "Adres pliku mp4 lub webm",
 "An online shop for my hand-poured soy candles, with a warm and calm look, best sellers on the home page and the story of how they are made.": "Sklep internetowy z moimi ręcznie odlewanymi świecami sojowymi, w ciepłym i spokojnym stylu, z bestsellerami na stronie głównej i historią ich powstawania.",
 "An order": "Zamówienie",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Zamówienie, wypłata, spór, Twoja strona lub coś, co nie działa. Prawdziwa osoba w Storelib czyta każde zgłoszenie i odpowiada tutaj.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Niezaznaczone pole „Wysyłaj mi nowości i oferty” pod e-mailem. Kampanie dostają tylko ci, którzy je zaznaczą.",
