 "Ask a buyer how it is going, seven days after they bought.": "Zapytaj kupującego, jak mu idzie, siedem dni po zakupie.",
 "Ask a few questions first": "Najpierw zadaj kilka pytań",
 "Ask about a product": "Zapytaj o produkt",
 "Ask an order": "Poproś zamówienie",
 "Ask an order for a review": "Poproś o opinię do zamówienia",
 "Ask buyers for a name, a message or a photo when they buy. You see their answers on the order.": "Poproś kupujących o imię, wiadomość lub zdjęcie przy zakupie. Odpowiedzi zobaczysz w zamówieniu.",
 "Ask for a change": "Poproś o zmianę",
 "Ask for a change, such as “make the hero taller”. It reads AGENTS.md first.": "Poproś o zmianę, np. „zrób baner wyższy”. Najpierw czyta AGENTS.md.",
 "Ask for a first name": "Pytaj o imię",
 "Ask for the next change": "Poproś o kolejną zmianę",
 "Ask the owner of {store} if you need it.": "Poproś właściciela {store}, jeśli tego potrzebujesz.",
 "Ask them to confirm by email first": "Najpierw poproś o potwierdzenie mailem",
 "Ask them to introduce themselves": "Poproś o przedstawienie się",
 "Ask them to read the rules": "Poproś o przeczytanie zasad",
 "Ask us anything": "Zapytaj nas o cokolwiek",
 "Ask your agent for a change": "Poproś agenta o zmianę",
 "Ask your audience a quick question": "Zadaj odbiorcom szybkie pytanie",
 "Asked": "Poproszono",
 "Asked before the questions were added.": "Prośba wysłana przed dodaniem pytań.",
 "Asked for news": "Chce dostawać wiadomości",
 "Asked for no emails": "Prosi o brak e-maili",
 "Asked in the last 7 days": "Poproszono w ciągu ostatnich 7 dni",
 "Asked to join": "Prosi o dołączenie",
 "Asking buyers if they want to hear from you, the way the law in most places expects.": "Pytanie kupujących, czy chcą otrzymywać wiadomości, jak wymaga prawo w większości krajów.",
 "Asking for rates": "Pobieranie stawek",
 "Aspect Ratio": "Proporcje",
 "Assets": "Zasoby",
