 "Automated messages need the database update for chat (run-now part 272).": "Wiadomości automatyczne wymagają aktualizacji bazy danych dla czatu (run-now część 272).",
 "Automatic": "Automatycznie",
 "Automatic link preview": "Automatyczny podgląd linku",
 "Automatic translation isn't set up on Storelib yet. You can still write each translation yourself.": "Automatyczne tłumaczenie nie jest jeszcze skonfigurowane w Storelib. Nadal możesz napisać każde tłumaczenie sam.",
 "Automatic translation keeps these words as written, or always uses your translation. Translations you write yourself are never changed.": "Automatyczne tłumaczenie zostawia te słowa bez zmian albo zawsze używa Twojego tłumaczenia. Tłumaczenia napisane przez Ciebie nigdy nie są zmieniane.",
 "Automatic translation leaves product titles as you wrote them. You can still translate a title yourself on the product's Translations card.": "Automatyczne tłumaczenie zostawia tytuły produktów tak, jak je napisano. Tytuł możesz nadal przetłumaczyć sam na karcie Tłumaczenia produktu.",
 "Automatic updates are not on yet": "Automatyczne aktualizacje nie są jeszcze włączone",
