 "Automatic updates paused for this package": "Wstrzymano automatyczne aktualizacje tej paczki",
 "Automatic updates turn on when Storelib's tracking is set up. Until then, orders keep the statuses you set and the carrier's tracking link, and buyers get the same emails when you change a status.": "Automatyczne aktualizacje włączą się po konfiguracji śledzenia Storelib. Do tego czasu zamówienia zachowują ustawione statusy i link przewoźnika, a kupujący dostają te same e-maile przy zmianie statusu.",
 "Automatic updates turn on when Storelib's tracking is set up. Until then, set the status from the menu.": "Automatyczne aktualizacje włączą się po konfiguracji śledzenia Storelib. Do tego czasu ustawiaj status z menu.",
