 "Buy a label": "Kup etykietę",
 "Buy and print labels from the order page at EasyPost's rates. The tracking number goes on the shipment.": "Kupuj i drukuj etykiety na stronie zamówienia po stawkach EasyPost. Numer śledzenia trafia do przesyłki.",
 "Buy and print labels from the order page at Shippo's rates. The tracking number goes on the shipment.": "Kupuj i drukuj etykiety na stronie zamówienia po stawkach Shippo. Numer śledzenia trafia do przesyłki.",
 "Buy for {priceLabel}": "Kup za {priceLabel}",
 "Buy for {price}": "Kup za {price}",
 "Buy it once and it is yours: here, and in your Storelib library with its receipt.": "Kup raz i jest twoje: tutaj i w twojej bibliotece Storelib z potwierdzeniem.",
 "Buy it together": "Kup razem",
 "Buy label · {price}": "Kup etykietę · {price}",
 "Buy me a coffee": "Postaw mi kawę",
 "Buy more of one product, pay less each, or get some free.": "Kup więcej jednego produktu, płać mniej za sztukę albo dostań część gratis.",
 "Buy more, save more": "Kup więcej, zapłać mniej",
 "Buy now": "Kup teraz",
 "Buy now and the cart open Storelib checkout. A cart with something to post asks for the address and delivery first.": "Kup teraz i koszyk otwierają kasę Storelib. Koszyk z produktem do wysyłki najpierw pyta o adres i dostawę.",
 "Buy opens Storelib checkout. Cards and Google Pay, through Stripe.": "Kup otwiera kasę Storelib. Karty i Google Pay przez Stripe.",
