 "Buy {quantity}, save {amount}": "Kup {quantity}, oszczędź {amount}",
 "Buy {quantity}, save {percent}%": "Kup {quantity}, oszczędź {percent}%",
 "Buy {title}": "Kup: {title}",
 "Buyer cases": "Sprawy kupujących",
 "Buyer's email or name": "E-mail lub imię kupującego",
 "Buyers add it for {amount}, instead of {amount2}.": "Kupujący dodają go za {amount} zamiast {amount2}.",
 "Buyers add it for {amount}.": "Kupujący dodają go za {amount}.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "Kupujący dostają prośbę e-mailem po zakupie, według Twojego harmonogramu w Storelib Reviews.",
 "Buyers are asked by email after they buy. Bring reviews from another app with Import.": "Kupujący dostają prośbę e-mailem po zakupie. Przenieś opinie z innej aplikacji przez Importuj.",
 "Buyers are asked by email after they buy. You can also import reviews from another app under Reviews.": "Kupujący dostają prośbę e-mailem po zakupie. Możesz też zaimportować opinie z innej aplikacji w zakładce Opinie.",
 "Buyers ask for a return from their order page, and you approve each one.": "Kupujący zgłaszają zwrot na stronie zamówienia, a Ty zatwierdzasz każdy.",
 "Buyers can add up to 4 photos. Each one is checked before it is kept.": "Kupujący mogą dodać do 4 zdjęć. Każde jest sprawdzane przed zapisaniem.",
 "Buyers can change their review for": "Kupujący mogą zmienić opinię przez",
 "Buyers can choose it": "Kupujący mogą go wybrać",
 "Buyers can collect their order here for free instead of having it shipped.": "Kupujący mogą odebrać tu zamówienie za darmo zamiast wysyłki.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Kupujący nie będą mogli go już użyć. Złożone z nim zamówienia zachowują rabat. Aby go na razie wstrzymać, wyłącz go.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now, turn it off instead.": "Kupujący nie będą mogli go już użyć. Złożone z nim zamówienia zachowują rabat. Aby wstrzymać go na razie, po prostu go wyłącz.",
 "Buyers can still order, and you ship when it's back.": "Kupujący mogą zamawiać, a Ty wyślesz po uzupełnieniu.",
 "Buyers can switch between cm and in. Columns with the ruler on are converted.": "Kupujący mogą przełączać między cm a in. Kolumny z włączoną linijką są przeliczane.",
 "Buyers can use it at checkout.": "Kupujący mogą go użyć przy płatności.",
 "Buyers can't check out a physical product until it has a rate for their address. Add a zone and a rate below.": "Kupujący nie kupią produktu fizycznego, dopóki nie będzie stawki dla ich adresu. Dodaj strefę i stawkę poniżej.",
 "Buyers can't check out on your store yet": "Kupujący nie mogą jeszcze płacić w Twoim sklepie",
 "Buyers can't check out until you do.": "Kupujący nie zapłacą, dopóki tego nie zrobisz.",
 "Buyers can't check out yet": "Kupujący nie mogą jeszcze płacić",
 "Buyers can't check out your physical products yet": "Kupujący nie mogą jeszcze kupić Twoich produktów fizycznych",
 "Buyers can't pay at checkout until this is done.": "Kupujący nie zapłacą, dopóki tego nie zrobisz.",
 "Buyers can't pay for anything until this is done.": "Kupujący nic nie zapłacą, dopóki tego nie zrobisz.",
 "Buyers choose Card or Cash on delivery at checkout. The order is placed at once and waits to be sent as usual. Mark it as paid from the order when you have the cash. No Storelib fee is taken on these orders.": "Kupujący wybierają przy kasie Kartę lub Płatność przy odbiorze. Zamówienie jest składane od razu i czeka na wysyłkę jak zwykle. Oznacz je jako opłacone w zamówieniu, gdy otrzymasz gotówkę. Storelib nie pobiera opłaty od tych zamówień.",
 "Buyers choose the price": "Kupujący wybierają cenę",
 "Buyers choose what to pay, from your minimum.": "Kupujący sami wybierają kwotę, od Twojego minimum.",
 "Buyers create an account or log in before checkout. Signed out visitors can still browse.": "Kupujący zakładają konto lub logują się przed zakupem. Niezalogowani nadal mogą przeglądać.",
 "Buyers keep their files and their access.": "Kupujący zachowują pliki i dostęp.",
 "Buyers never see it": "Kupujący tego nie widzą",
 "Buyers only": "Tylko kupujący",
 "Buyers only see it struck through when it is higher than the price.": "Kupujący widzą ją przekreśloną tylko, gdy jest wyższa niż cena.",
 "Buyers open it from Size guide on the product page.": "Kupujący otwierają ją przez Przewodnik po rozmiarach na stronie produktu.",
 "Buyers pay your prices and nothing more.": "Kupujący płacą Twoje ceny i nic więcej.",
 "Buyers reply to order emails. Right now replies go to your login email.": "Kupujący odpowiadają na e-maile o zamówieniach. Teraz odpowiedzi trafiają na e-mail logowania.",
 "Buyers review from their receipt or their library. Storelib asks them a week after they buy on Storelib, and again a week later if they have not.": "Kupujący wystawiają opinię z potwierdzenia lub biblioteki. Storelib prosi o nią tydzień po zakupie w Storelib i ponownie tydzień później, jeśli jej nie dodali.",
 "Buyers see it as sold out. Add stock, or let it keep selling when it runs out.": "Kupujący widzą go jako wyprzedany. Dodaj towar lub pozwól sprzedawać po wyczerpaniu.",
 "Buyers see it as the title of the chart.": "Kupujący widzą ją jako tytuł tabeli.",
 "Buyers see it when they choose pickup": "Kupujący widzą to przy wyborze odbioru",
 "Buyers see it where it shows.": "Kupujący widzą ją tam, gdzie się wyświetla.",
 "Buyers see them as sold out. Add stock, or let them keep selling when they run out.": "Kupujący widzą je jako wyprzedane. Dodaj towar lub pozwól sprzedawać po wyczerpaniu.",
 "Buyers see these words on the event page and in their receipt.": "Kupujący zobaczą ten tekst na stronie wydarzenia i na paragonie.",
 "Buyers see “Name a fair price”, starting at your suggested amount.": "Kupujący widzą „Zaproponuj uczciwą cenę”, zaczynając od Twojej sugerowanej kwoty.",
 "Buyers watch these in their library, and pick up where they left off.": "Kupujący oglądają je w bibliotece i wznawiają tam, gdzie skończyli.",
 "Buyers who are subscribers get the Storelib buyer tag, refunds Storelib refunded": "Kupujący, którzy są subskrybentami, dostają tag Storelib buyer, zwroty Storelib refunded",
 "Buyers who are subscribers join Storelib buyers, refunds join Storelib refunded": "Kupujący, którzy są subskrybentami, trafiają do Storelib buyers, zwroty do Storelib refunded",
 "Buyers who asked to hear from you when they paid.": "Kupujący, którzy przy płatności poprosili o wiadomości od Ciebie.",
 "Buyers who choose pickup aren't told when they can come.": "Osoby wybierające odbiór nie wiedzą, kiedy mogą przyjść.",
 "Buyers who did not ask for news. They get emails about what they bought, never one you send to your list.": "Kupujący, którzy nie prosili o wiadomości. Dostają e-maile o swoich zakupach, nigdy te wysyłane do listy.",
 "Buyers who did not ask, as contacts on no list": "Kupujący, którzy o to nie prosili, jako kontakty bez listy",
