 "Downloads, courses and memberships. In the EU, VAT on digital sales is charged at the rate of the buyer's country, so add a region for each country you sell to.": "Pliki, kursy i członkostwa. W UE VAT od sprzedaży cyfrowej nalicza się według stawki kraju kupującego, więc dodaj region dla każdego kraju, do którego sprzedajesz.",
