 "Drag the grip, or hold a card, to move it. With the keyboard, the up and down arrows move it one place.": "Przeciągnij uchwyt lub przytrzymaj kartę, aby ją przenieść. Na klawiaturze strzałki w górę i w dół przesuwają ją o jedno miejsce.",
 "Drag the picture to choose what stays in view where it is cropped: the card beside your page, your card in Explore.": "Przeciągnij zdjęcie, aby wybrać, co zostaje widoczne po przycięciu: karta obok twojej strony, twoja karta w Odkrywaj.",
