 "Imported as drafts. Nothing is published.": "Importowane jako szkice. Nic nie jest publikowane.",
 "Imported from {app}": "Zaimportowano z {app}",
 "Imported reviews are marked Imported. They can show on your website, but they never get the Verified purchase label and never count in your Storelib rating.": "Zaimportowane opinie są oznaczone jako Zaimportowane. Mogą być widoczne na Twojej stronie, ale nigdy nie dostają etykiety Zweryfikowany zakup i nie liczą się do Twojej oceny w Storelib.",
 "Imported theme": "Zaimportowany motyw",
 "Imported themes show their own stars from the same ratings.": "Zaimportowane motywy pokazują własne gwiazdki z tych samych ocen.",
 "Imported {value}{value2}": "Zaimportowano {value}{value2}",
 "Importing": "Importowanie",
 "Importing {done} of {total}": "Importowanie {done} z {total}",
 "Importing…": "Importowanie…",
 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Szkielety ładowania w Odkrywaj, Statystykach i Planach lepiej odpowiadają prawdziwym stronom.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Ustawienia z płynniejszym paskiem zapisu, powiadomieniami i szybszym przełączaniem kart.",
 "Improvement": "Ulepszenie",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "W 17TRACK, Settings > Webhook: dodaj ten adres. 17TRACK podpisuje aktualizacje Twoim kluczem API. Bez tego Storelib sprawdza co kilka godzin.",
 "In AfterShip, Settings > Webhooks: add this address, then paste its webhook secret under Change key, so updates arrive the moment they happen. Without it Storelib checks every few hours.": "W AfterShip, Settings > Webhooks: dodaj ten adres, a potem wklej sekret webhooka w Zmień klucz, aby aktualizacje docierały od razu. Bez tego Storelib sprawdza co kilka godzin.",
 "In Brevo, open SMTP and API, API keys.": "W Brevo otwórz SMTP i API, Klucze API.",
 "In Flodesk, open Account settings, Integrations, API keys.": "W Flodesk otwórz Ustawienia konta, Integracje, Klucze API.",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "W Gelato, Developer › Webhooks, dodaj ten adres dla statusu zamówień i numerów śledzenia:",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking updates.": "W Gelato, w Developer › Webhooks, dodaj ten adres, aby otrzymywać status zamówień i śledzenie przesyłek.",
 "In Google Ads, open Goals › Conversions › New conversion action › Import › Google Analytics 4 and pick them.": "W Google Ads otwórz Cele › Konwersje › Nowe działanie powodujące konwersję › Importuj › Google Analytics 4 i wybierz je.",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "W Google Analytics Raporty › Czas rzeczywisty pokazują wizytę w ciągu minuty. Komunikat „Zbieranie danych nie jest aktywne” przy strumieniu może zniknąć dopiero po 48 godzinach.",
 "In Google Analytics, open Admin › Product links › Google Ads links and link your Ads account.": "W Google Analytics otwórz Administracja › Połączenia z usługami › Połączenia z Google Ads i połącz swoje konto Ads.",
 "In Gumroad, open Settings › Advanced.": "W Gumroad otwórz Settings › Advanced.",
 "In Kit, open Settings, Developer.": "W Kit otwórz Ustawienia, Deweloper.",
 "In Mailchimp, open Profile, Extras, API keys.": "W Mailchimp otwórz Profil, Dodatki, Klucze API.",
 "In MailerLite, open Integrations, API.": "W MailerLite otwórz Integracje, API.",
 "In Make, add a Webhooks module, Custom webhook.": "W Make dodaj moduł Webhooks, Custom webhook.",
 "In Zapier, start a Zap with Webhooks by Zapier, Catch Hook.": "W Zapier zacznij Zap od Webhooks by Zapier, Catch Hook.",
 "In a trial": "W okresie próbnym",
 "In another zone": "W innej strefie",
 "In app": "W aplikacji",
 "In beehiiv, open Settings, API.": "W beehiiv otwórz Ustawienia, API.",
