 "In the community": "W społeczności",
 "In the domain's hosted zone, leave Record name empty for the domain itself.": "W strefie hostowanej domeny zostaw nazwę rekordu pustą dla samej domeny.",
 "In the last lab test, files that hold up the first paint cost {time}.": "W ostatnim teście laboratoryjnym pliki blokujące pierwsze wyświetlenie kosztowały {time}.",
 "In the last lab test, the heaviest image was {file} at {size}.": "W ostatnim teście laboratoryjnym najcięższym obrazem był {file} ({size}).",
