 "Memberships end today. Each member gets back what they paid for the time left, about {amount} in all. This cannot be undone.": "Członkostwa kończą się dziś. Każdy członek odzyska to, co zapłacił za pozostały czas, łącznie około {amount}. Tego nie da się cofnąć.",
 "Memberships ended with refunds. It is deleted once every refund has gone through.": "Członkostwa zakończono ze zwrotem pieniędzy. Zostanie usunięta, gdy wszystkie zwroty dojdą do skutku.",
 "Memberships renew again as before and the community comes back the way it was. Members are told by email.": "Członkostwa znów się odnawiają, a społeczność wraca do poprzedniego stanu. Członkowie dostaną e-mail.",
 "Memberships stopped renewing and nobody new can join. Members can read it until then. {stopped} of {total} memberships stopped.": "Członkostwa nie odnawiają się i nikt nowy nie może dołączyć. Do tego czasu członkowie mogą ją czytać. Zatrzymano {stopped} z {total} członkostw.",
