 "Of the people who visited, how many opened a product, added it to the cart or pressed Buy, started a checkout, and how many orders came in. Each step is a share of the one before; the step that loses the most people is marked in red.": "Spośród odwiedzających: ilu otworzyło produkt, dodało go do koszyka lub nacisnęło Kup, rozpoczęło płatność i ile zamówień przyszło. Każdy krok to część poprzedniego; krok, który traci najwięcej osób, jest zaznaczony na czerwono.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Ilu odwiedzających otworzyło produkt, ilu zaczęło płatność i ile zamówień wpłynęło. Każdy krok pokazano jako część poprzedniego.",
 "Of this period's physical orders, the share that has been shipped or delivered, and how long a parcel waited from payment to shipped.": "Z zamówień fizycznych z tego okresu odsetek wysłanych lub doręczonych oraz to, ile paczka czekała od płatności do wysyłki.",
