 "Only verified buyers count toward your Storelib rating and get the Verified purchase label. Imported and visitor reviews can show on your website, but never count there.": "Tylko zweryfikowani kupujący liczą się do Twojej oceny w Storelib i dostają etykietę Zweryfikowany zakup. Opinie zaimportowane i od odwiedzających mogą być widoczne na Twojej stronie, ale tam się nie liczą.",
