 "Optional, for your history": "Opcjonalnie, do historii",
 "Optional, for your records and your accountant": "Opcjonalnie, do Twojej dokumentacji i dla księgowego",
 "Optional, https://": "Opcjonalnie, https://",
 "Optional, like usps_priority (Shippo) or Priority (EasyPost). Empty: the cheapest.": "Opcjonalnie, np. usps_priority (Shippo) lub Priority (EasyPost). Puste: najtańsza.",
 "Optional, the carrier's page for this parcel": "Opcjonalnie, strona przewoźnika dla tej paczki",
 "Optional. A line under the name, for you.": "Opcjonalnie. Linijka pod nazwą, dla Ciebie.",
 "Optional. Drag to reorder images.": "Opcjonalnie. Przeciągnij, aby zmienić kolejność.",
 "Optional. Each paid order for this product is emailed here with the items and address. Empty: you pass orders on yourself.": "Opcjonalnie. Każde opłacone zamówienie tego produktu trafi tu e-mailem z produktami i adresem. Puste: przekazujesz zamówienia sam.",
 "Optional. Empty: always free.": "Opcjonalnie. Puste: zawsze za darmo.",
 "Optional. How to measure, or how it fits.": "Opcjonalnie. Jak mierzyć albo jak leży.",
 "Optional. Labels and return emails use it.": "Opcjonalne. Używają go etykiety i e-maile o zwrotach.",
 "Optional. Leave it empty to always charge.": "Opcjonalne. Zostaw puste, aby zawsze pobierać opłatę.",
 "Optional. Listed countries see and pay in their currency. Everyone else sees {currency}.": "Opcjonalnie. Wymienione kraje widzą i płacą w swojej walucie. Pozostali widzą {currency}.",
 "Optional. Put {tracking} where the number goes.": "Opcjonalnie. Wpisz {tracking} tam, gdzie ma być numer.",
 "Optional. The code after # on the order.": "Opcjonalnie. Kod po # w zamówieniu.",
 "Optional. Visitors from other countries see prices converted to their currency. Checkout always charges {currency}.": "Opcjonalnie. Odwiedzający z innych krajów widzą ceny przeliczone na swoją walutę. Przy kasie zawsze pobierana jest kwota w {currency}.",
 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Opcjonalnie. Odwiedzający z innych krajów widzą Twoje ceny w swojej walucie i w niej płacą.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Opcjonalne. Odwiedzający z krajów, które wskażesz, widzą ceny w tej walucie i w niej płacą. Pozostali widzą {currency}. Każdy może zmienić walutę w przełączniku na Twojej stronie.",
 "Optional. Visitors in these countries see your prices in their currency, can switch with your website's currency selector, and pay in it.": "Opcjonalnie. Odwiedzający z tych krajów widzą ceny w swojej walucie, mogą ją zmienić selektorem waluty na Twojej stronie i w niej płacą.",
 "Optional. What it's for, for you and your team.": "Opcjonalnie. Do czego służy, dla Ciebie i zespołu.",
 "Optional. Where a tap on the picture goes.": "Opcjonalnie. Dokąd prowadzi kliknięcie obrazu.",
 "Optional. Where to measure, shown above the table.": "Opcjonalnie. Gdzie mierzyć, widoczne nad tabelą.",
 "Optional. Your profile photo stays separate.": "Opcjonalnie. Zdjęcie profilowe zostaje osobno.",
 "Optional: free once the order reaches this": "Opcjonalnie: za darmo, gdy zamówienie osiągnie tę wartość",
