 "Storelib's fee for your plan ({freeFee} on Free, {proFee} on Pro), and Stripe's card processing fee, which Stripe charges on every plan. There is nothing else.": "Prowizja Storelib dla Twojego planu ({freeFee} w Free, {proFee} w Pro) i opłata Stripe za obsługę karty, pobierana w każdym planie. Nic więcej.",
 "Storelib's words, because it is about someone's money. As a member of {name} gets it, in English.": "Słowa Storelib, bo chodzi o czyjeś pieniądze. Tak, jak dostaje go członek {name}, po angielsku.",
 "Storelib, automatically": "Storelib, automatycznie",
