 "This site follows {value}. Follow {branch} instead to bring it in now, or merge it into {value2} on GitHub.": "Ta strona śledzi {value}. Śledź zamiast tego {branch}, aby pobrać to teraz, albo scal to z {value2} na GitHubie.",
 "This site follows {value}. Merge it into {value2} on GitHub to bring it in.": "Ta strona śledzi {value}. Scal to z {value2} w GitHub, aby pobrać.",
 "This site uses its own copy of this built-in section. Other sites keep Storelib's.": "Ta strona używa własnej kopii tej wbudowanej sekcji. Inne strony mają wersję Storelib.",
 "This store has no communities yet. The owner makes them.": "Ten sklep nie ma jeszcze społeczności. Tworzy je właściciel.",
 "This text": "Ten tekst",
