 "This text appears on your customers' bank statements. It helps them identify the charge. Format: \"(Your Name) - STORELIB\". Only your name can be changed. Max 22 characters total.": "Ten tekst pojawia się na wyciągach klientów i pomaga im rozpoznać obciążenie. Format: „(Twoja nazwa) - STORELIB”. Zmienić można tylko nazwę. Łącznie maks. 22 znaki.",
