 "To": "Do",
 "To GitHub": "Do GitHub",
 "To count stock, have it fulfilled from one of your own locations.": "Aby liczyć stan, realizuj z jednej ze swoich lokalizacji.",
 "To days": "Do (dni)",
 "To do": "Do zrobienia",
 "To do ({count})": "Do zrobienia ({count})",
 "To hand it over in person, turn on local pickup in Settings › Shipping.": "Aby przekazać go osobiście, włącz odbiór osobisty w Ustawieniach › Wysyłka.",
 "To keep your payouts going, Stripe asks for this now{value}. It takes a minute.": "Aby wypłaty działały dalej, Stripe prosi o to teraz{value}. To zajmie minutę.",
 "To make one link stand out, use the sparkle button on that link in Links.": "Aby wyróżnić jeden link, użyj przycisku z iskierkami przy tym linku w Linkach.",
 "To move a photo or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is the thumbnail.": "Aby przenieść zdjęcie lub wideo, naciśnij na nim Spację lub Enter, a potem strzałki. Naciśnij Spację lub Enter ponownie, aby upuścić, albo Escape, aby cofnąć. Pierwsze jest miniaturą.",
 "To move a picture or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is shown first.": "Aby przenieść zdjęcie lub wideo, naciśnij na nim Spację lub Enter, potem strzałki. Naciśnij ponownie Spację lub Enter, aby upuścić, albo Escape, aby odłożyć na miejsce. Pierwsze jest pokazywane jako pierwsze.",
 "To move a question, press Space or Enter on its handle, then the up and down arrow keys. Press Space or Enter again to drop it, or Escape to put it back.": "Aby przenieść pytanie, naciśnij Spację lub Enter na uchwycie, a potem strzałki w górę i w dół. Naciśnij Spację lub Enter ponownie, aby upuścić, albo Escape, aby cofnąć.",
 "To move a space, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Aby przenieść przestrzeń, naciśnij Enter na jej uchwycie, potem strzałki. Naciśnij ponownie Enter, aby upuścić, albo Escape, aby odłożyć na miejsce.",
 "To move an item, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Aby przenieść element, naciśnij Enter na jego uchwycie, a potem strzałki. Naciśnij Enter ponownie, aby go upuścić, lub Escape, aby go cofnąć.",
 "To move an option, press Space on its handle, then the up and down arrow keys, then Space again.": "Aby przenieść opcję, naciśnij Spację na uchwycie, potem strzałki w górę i w dół, a potem znowu Spację.",
 "To send a product here: in the product, choose Print on demand and the {value} location, and give each variant the same SKU it has in {name}.": "Aby wysyłać tu produkt: w produkcie wybierz Druk na żądanie i lokalizację {value} oraz nadaj każdemu wariantowi ten sam SKU co w {name}.",
 "To send a product here: in the product, choose {value} and the {value2} location, then match each variant to {name}'s below.": "Aby wysyłać tu produkt: w produkcie wybierz {value} i lokalizację {value2}, a potem dopasuj każdy wariant do wariantów {name} poniżej.",
