 "When a paid membership ends and access stops.": "Gdy płatne członkostwo się kończy i dostęp się zatrzymuje.",
 "When a paid membership is cancelled": "Gdy płatne członkostwo zostanie anulowane",
 "When a paid membership starts": "Gdy zaczyna się płatne członkostwo",
 "When a review comes in": "Gdy pojawi się opinia",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Gdy wysyłka zostanie oznaczona jako nieudana: przewoźnik lub Twoja dostawa nie zdołała jej doręczyć.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Gdy właściciel sklepu Cię zaprosi, sklep pojawi się tutaj i otworzysz go ze swojego konta.",
 "When a ticket is refunded.": "Gdy bilet zostaje zwrócony.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Kiedy kupujący mogą przyjść. Widoczne w kasie i w e-mailu o odbiorze.",
 "When does Pro pay for itself?": "Kiedy Pro się zwraca?",
 "When it is sent": "Kiedy jest wysyłana",
 "When it pushes to": "Gdy wypchnie do",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Gdy wypchnie zmiany do {branch}, pojawią się tu jako szkic w kilka sekund.",
 "When it's marked delivered.": "Gdy zostanie oznaczona jako doręczona.",
 "When members leave they can say why. Their answers show up here.": "Odchodząc, członkowie mogą podać powód. Odpowiedzi pojawią się tutaj.",
 "When members report a post, a comment or somebody, it lands here.": "Gdy członkowie zgłoszą post, komentarz lub osobę, trafi to tutaj.",
 "When memberships end": "Kiedy kończą się członkostwa",
 "When pressed": "Po naciśnięciu",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Gdy zwroty są włączone, kupujący widzi Poproś o zwrot na stronie zamówienia przez cały termin zwrotu.",
 "When review emails go, and what they say, is under Requests.": "Kiedy wychodzą e-maile z prośbą o opinię i co w nich jest, ustawisz w zakładce Prośby.",
 "When somebody asks to join, they show here with their answers.": "Gdy ktoś poprosi o dołączenie, pojawi się tu ze swoimi odpowiedziami.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Gdy ktoś napisze przez formularz kontaktowy na Twojej stronie, wiadomość pojawi się tutaj i w Twojej skrzynce.",
 "When someone buys a ticket to a paid event, with the calendar file.": "Gdy ktoś kupuje bilet na płatne wydarzenie, z plikiem kalendarza.",
 "When someone joins": "Gdy ktoś dołącza",
 "When someone joins a membership you sell on its own, with what they pay and when.": "Gdy ktoś dołącza do członkostwa sprzedawanego osobno, z tym, ile i kiedy płaci.",
 "When someone joins a paid plan, with what they pay and when.": "Gdy ktoś dołącza do płatnego planu, z tym, ile i kiedy płaci.",
 "When someone joins your list": "Gdy ktoś zapisze się na listę",
 "When someone joins, or is let back in.": "Gdy ktoś dołącza lub zostaje przyjęty z powrotem.",
 "When someone leaves checkout": "Gdy ktoś porzuci płatność",
 "When someone starts a membership": "Gdy ktoś zaczyna członkostwo",
 "When someone taps it": "Gdy ktoś go kliknie",
 "When the bank declines a renewal. It asks the member to update their card.": "Gdy bank odrzuci odnowienie. Prosi członka o zaktualizowanie karty.",
 "When the carrier says it's out for delivery.": "Gdy przewoźnik poda, że paczka jest w doręczeniu.",
 "When the items reach you.": "Gdy produkty do Ciebie dotrą.",
 "When the next scheduled email is sent.": "Kiedy wyjdzie następny zaplanowany e-mail.",
 "When the return is closed, with any refund.": "Gdy zwrot zostanie zamknięty, z ewentualną refundacją.",
 "When their paid time runs out": "Gdy skończy się opłacony okres",
 "When they go": "Kiedy wychodzą",
 "When visitors subscribe, they can download \"": "Po zapisaniu odwiedzający mogą pobrać „",
 "When will my order arrive?": "Kiedy dotrze moje zamówienie?",
 "When you add a product, ship an order or change a setting, it shows up here.": "Gdy dodasz produkt, wyślesz zamówienie lub zmienisz ustawienie, pojawi się to tutaj.",
 "When you approve a request to join": "Gdy zaakceptujesz prośbę o dołączenie",
 "When you approve a request to join. In a paid community it says how to finish joining.": "Gdy akceptujesz prośbę o dołączenie. W płatnej społeczności mówi, jak dokończyć dołączanie.",
 "When you approve a return, with your instructions.": "Gdy zatwierdzisz zwrot, z instrukcjami.",
 "When you cancel a paid event. It says the money is on its way.": "Gdy odwołujesz płatne wydarzenie. Mówi, że pieniądze są w drodze.",
 "When you cancel an order before it ships.": "Gdy anulujesz zamówienie przed wysyłką.",
 "When you change the shipping address on an order before it ships.": "Gdy zmienisz adres wysyłki przed nadaniem.",
 "When you change the tracking number on a shipment that already went out.": "Gdy zmienisz numer śledzenia już wysłanej paczki.",
 "When you decline a return, with your note.": "Gdy odrzucisz zwrot, z notatką.",
 "When you give someone a ticket.": "Gdy dajesz komuś bilet.",
 "When you invite someone by email": "Gdy zapraszasz kogoś e-mailem",
 "When you invite someone by email.": "Gdy zapraszasz kogoś e-mailem.",
