 "When you mark it collected.": "Gdy oznaczysz je jako odebrane.",
 "When you mark items shipped, with the tracking.": "Gdy oznaczysz produkty jako wysłane, z numerem śledzenia.",
 "When you post an announcement": "Gdy publikujesz ogłoszenie",
 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Gdy opublikujesz zmiany, nowy i zmieniony tekst zostanie przetłumaczony na Twoje pozostałe języki w kilka minut. Tłumaczenia, które edytujesz sam, nigdy nie są zastępowane.",
 "When you published": "Przy publikacji",
 "When you refund a download, course or membership, here or in Stripe. Its download stops working.": "Gdy zwracasz pieniądze za plik, kurs lub członkostwo, tutaj lub w Stripe. Jego pobieranie przestaje działać.",
 "When you refund all or part of an order, here or in Stripe.": "Gdy zwrócisz całość lub część zamówienia, tutaj lub w Stripe.",
 "When you write one. It goes to members who keep community emails on, one a day at most.": "Gdy go napiszesz. Trafia do członków, którzy mają włączone e-maile społeczności, najwyżej jeden dziennie.",
 "Where": "Gdzie",
 "Where answers go": "Dokąd trafiają odpowiedzi",
 "Where are you based?": "Gdzie działasz?",
 "Where buyers collect their orders. For your default location, it's also where return emails tell buyers to send items.": "Gdzie kupujący odbierają zamówienia. Dla domyślnej lokalizacji to także adres zwrotów w e-mailach.",
 "Where do you ship from?": "Skąd wysyłasz?",
 "Where each order was placed: each of your websites by its name, your OnePage, your creator page, Storelib Explore or a checkout link opened on its own.": "Gdzie złożono każde zamówienie: każda z Twoich stron po nazwie, Twoja OnePage, Twoja strona twórcy, Storelib Explore lub samodzielnie otwarty link do płatności.",
 "Where each order was placed: your online store, Storelib (Explore, product and creator pages, communities), your OnePage or a checkout link.": "Gdzie złożono każde zamówienie: Twój sklep internetowy, Storelib (Explore, strony produktów i twórców, społeczności), Twoja OnePage lub link do płatności.",
 "Where each visit came from, judged by its first page: a search engine, a social app, an email, another website, or typed in directly.": "Skąd przyszła każda wizyta, według jej pierwszej strony: wyszukiwarka, media społecznościowe, e-mail, inna strona lub wpisany adres.",
