 "Where this period's money came from, and the members paying for the community.": "Skąd pochodziły pieniądze w tym okresie i którzy członkowie płacą za społeczność.",
 "Where this period's money came from, less refunds: memberships and purchases, programs, event tickets. By plan: each plan by the name it is sold under, with the members paying for it at the end of the period.": "Skąd przyszły pieniądze w tym okresie, po zwrotach: członkostwa i zakupy, programy, bilety na wydarzenia. Według planu: każdy plan pod nazwą, pod którą jest sprzedawany, z członkami płacącymi za niego na koniec okresu.",
