 "Where you live. A PO box or military address cannot be verified.": "Gdzie mieszkasz. Skrytki pocztowej ani adresu wojskowego nie da się zweryfikować.",
 "Where you live. It sets your payout currency and which ID Stripe asks for, and cannot be changed after you continue.": "Gdzie mieszkasz. Ustala walutę wypłat i dokument wymagany przez Stripe; po przejściu dalej nie można tego zmienić.",
