 "Wins": "Sukcesy",
 "With Show visitors their own language on, a first visit opens in the published language the browser asks for, once. A close match, or only the country to go by, gets a small offer on the page instead. A market can also start its countries in its own language. After that the visitor's choice wins, and search engines still see every language at its own address.": "Gdy „Pokazuj odwiedzającym ich język” jest włączone, pierwsza wizyta otwiera się raz w opublikowanym języku, o który prosi przeglądarka. Przy podobnym języku lub samym kraju na stronie pojawia się mała propozycja. Rynek może też otwierać swoje kraje we własnym języku. Potem liczy się wybór odwiedzającego, a wyszukiwarki nadal widzą każdy język pod jego własnym adresem.",
