 "Your payout account, plan and other businesses stay with you. They connect their own payouts.": "Twoje konto wypłat, plan i inne firmy zostają u ciebie. Druga osoba podłącza własne wypłaty.",
 "Your personal info, a quick ID check with Stripe, then your bank. About five minutes.": "Dane osobowe, szybka weryfikacja tożsamości ze Stripe, potem bank. Około pięciu minut.",
 "Your personal info, then your bank. About five minutes.": "Dane osobowe, potem bank. Około pięciu minut.",
 "Your phone is shown to your payment provider and on order emails, so a buyer or a carrier can reach you about an order.": "Telefon widzi operator płatności i jest w e-mailach o zamówieniach, aby kupujący lub kurier mógł się skontaktować.",
 "Your photo": "Twoje zdjęcie",
 "Your picture fills the top of the page and fades into it.": "Obraz wypełnia górę strony i płynnie w nią przechodzi.",
 "Your pictures": "Twoje obrazy",
