 "Your plan": "Twój plan",
 "Your plan will downgrade at the end of your current billing cycle. You'll keep all current features until then.": "Plan zmieni się na niższy na koniec bieżącego okresu rozliczeniowego. Do tego czasu zachowasz wszystkie obecne funkcje.",
 "Your plan, invoices and payment card": "Twój plan, faktury i karta płatnicza",
 "Your posts are listed at {address}.": "Twoje wpisy są na {address}.",
 "Your prices": "Twoje ceny",
 "Your prices ({currency})": "Twoje ceny ({currency})",
 "Your prices are in it and buyers pay in it. Payouts still arrive in your bank's currency.": "Twoje ceny są w tej walucie i kupujący w niej płacą. Wypłaty nadal trafiają w walucie Twojego banku.",
 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Twoje ceny są w {baseCurrency}. Karty są obciążane w {chargeCurrency}. Rynek w innej walucie pokazuje szacunek po kursie Europejskiego Banku Centralnego i informuje o tym przed płatnością.",
 "Your prices, your website, the builder and checkout all use it.": "Używają jej Twoje ceny, strona, edytor i płatność.",
 "Your product has no stock yet. Add some so buyers can order it.": "Produkt nie ma jeszcze stanu. Dodaj towar, aby kupujący mogli zamawiać.",
 "Your products": "Twoje produkty",
 "Your products, pages, customers and orders stay as they are.": "Produkty, strony, klienci i zamówienia pozostaną bez zmian.",
 "Your products, pages, customers and orders stay exactly as they are. The Free fee applies to new sales, and the things only Pro has, like your own domain and hidden branding, stop at the end of your paid period.": "Produkty, strony, klienci i zamówienia zostają bez zmian. Do nowej sprzedaży stosuje się prowizję Free, a funkcje tylko z Pro, jak własna domena i ukryta marka, wyłączą się z końcem opłaconego okresu.",
 "Your profile name and photo, as they are now.": "Imię i zdjęcie z twojego profilu, takie jak teraz.",
 "Your profile photo, until you choose a logo.": "Twoje zdjęcie profilowe, dopóki nie wybierzesz logo.",
 "Your profiles as a row of icons": "Twoje profile jako rząd ikon",
 "Your programs and lessons, inside the community.": "Twoje programy i lekcje wewnątrz społeczności.",
 "Your questions": "Twoje pytania",
 "Your rates go by weight, so without one they ship at the lightest price.": "Stawki zależą od wagi, więc bez niej wysyłka idzie po najniższej cenie.",
 "Your receipt for The bread baking course": "Paragon za Kurs pieczenia chleba",
 "Your reply": "Twoja odpowiedź",
 "Your reply was not sent. Try again.": "Twoja odpowiedź nie została wysłana. Spróbuj ponownie.",
 "Your requests": "Twoje zgłoszenia",
 "Your return window and a link to your refund policy, under Check out.": "Termin zwrotu i link do regulaminu zwrotów, pod przyciskiem Do kasy.",
 "Your return window and the reasons a buyer can choose.": "Termin zwrotu i powody, które kupujący może wybrać.",
 "Your role can review reports but not remove content.": "Twoja rola może przeglądać zgłoszenia, ale nie usuwać treści.",
 "Your role in this community cannot do that.": "Twoja rola w tej społeczności na to nie pozwala.",
 "Your sales show up here as soon as someone buys, with what they paid and what you keep.": "Sprzedaż pojawi się tu, gdy tylko ktoś kupi, z kwotą zapłaconą i tym, co zostaje dla Ciebie.",
 "Your session ended. Sign in again to use Storelib AI.": "Sesja wygasła. Zaloguj się ponownie, aby używać Storelib AI.",
