 "Your store logo.": "Logo sklepu.",
 "Your store name": "Nazwa sklepu",
 "Your store opens in three steps": "Twój sklep otworzysz w trzech krokach",
 "Your store was not saved": "Sklep nie został zapisany",
 "Your store's contact email, from Settings › Store details. A buyer who answers an email writes to it.": "Kontaktowy e-mail sklepu z Ustawienia › Dane sklepu. Kupujący, który odpowie na e-mail, napisze właśnie tam.",
 "Your store's country": "Kraj Twojego sklepu",
 "Your store's database is missing the blog's tables. Once SQL part 355 has been run, posts, categories and authors are kept here.": "W bazie danych Twojego sklepu brakuje tabel bloga. Po uruchomieniu części SQL 355 wpisy, kategorie i autorzy będą tutaj.",
 "Your store's name and contact details go on receipts, order emails and your checkout, so buyers know who they bought from.": "Nazwa i dane kontaktowe sklepu są na paragonach, w e-mailach i w kasie, by kupujący wiedzieli, od kogo kupili.",
 "Your store, products, customers and details are removed. People who bought from you keep what they bought, and your sales and payout records are kept.": "Sklep, produkty, klienci i dane zostaną usunięte. Kupujący zachowają to, co kupili, a historia sprzedaży i wypłat zostanie zachowana.",
