 "Your subscribers who said yes, and the orders of the last 90 days, in batches. A Kit automation that starts on the tag may run for them.": "Twoi subskrybenci, którzy się zgodzili, i zamówienia z ostatnich 90 dni, partiami. Automatyzacja Kit, która startuje od tagu, może się dla nich uruchomić.",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. A MailerLite automation that starts when someone joins the group may run for them.": "Twoi subskrybenci, którzy się zgodzili, i zamówienia z ostatnich 90 dni, partiami. Automatyzacja MailerLite, która startuje po dołączeniu do grupy, może się dla nich uruchomić.",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. Past orders are sent as history, so no automation emails them again.": "Subskrybenci, którzy się zgodzili, i zamówienia z ostatnich 90 dni, partiami. Starsze zamówienia idą jako historia, więc żadna automatyzacja nie napisze do nich ponownie.",
